contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // sendAmount: amount of wei to forward through c.go
    // ownerBefore: observed owner balance before calling go
    function run(uint sendAmount) public payable {
        require(sendAmount > 0, "need positive amount");
        require(address(this).balance >= sendAmount, "insufficient test balance");

        // record owner's balance before
        uint ownerBefore = c.owner().balance;

        // call go sending Ether to c
        c.go{value: sendAmount}();

        // after go, c should have forwarded funds to owner
        // check c's balance is zero and owner's balance increased by at least sendAmount
        // (exactly sendAmount because c had no prior balance in this simple scenario)
        assert(address(c).balance == 0 && c.owner().balance >= ownerBefore + sendAmount);
    }

    // allow this contract to receive ETH for testing
    receive() external payable {}
}

