import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    // Helper callee that accepts some ETH and leaves a remainder in C by consuming less than forwarded
    contract Callee {
        // accept funds but do nothing else
        fallback() external payable {}
    }

    function setUp() public { c = new C(); }

    // General rule: after go() returns (when the callee does not revert), owner always receives any leftover balance
    // We fuzz the sent amount and the amount the adversarial callee will consume by making the callee accept but not forward funds.
    function testFuzz_property(uint256 sendAmount, address caller) public {
        // keep caller a valid EOA for prank and avoid zero-address confusion
        vm.assume(caller != address(0));
        // bound sendAmount to a reasonable range
        sendAmount = bound(sendAmount, 1, 1 ether);

        // deploy a callee that will accept the forwarded call (non-reverting)
        Callee callee = new Callee();

        // fund the caller so it can send ETH
        vm.deal(caller, sendAmount);

        // record owner balance before
        address owner = c.owner();
        uint256 ownerBalBefore = owner.balance;

        // invoke go from caller sending sendAmount; the callee is the fixed hard-coded address inside C, so we need to
        // ensure that the address used by C (0xC8A6...) points to our callee. We cannot change C's hardcoded address,
        // so instead we simulate by deploying a contract at that address using vm.prank and raw create isn't allowed here.
        // However, the difference manifests when the callee returns successfully; using any externally owned account as target
        // would make the call succeed and not consume funds. To exercise leftover forwarding we rely on the call succeeding
        // (callee accepts). We'll make the call from caller to c.go which will perform target.call; because fuzzed addresses
        // for target are fixed in C, the call to that fixed address will succeed (EOA) and leave entirety of sent ETH in C.
        // The important observable is that reference sends leftover to owner; mutant sends to msg.sender. So we drive c.go.

        vm.prank(caller);
        c.go{value: sendAmount}();

        // After go returns, the reference guarantees owner received leftover funds (i.e., owner balance increased by sendAmount and contract has zero)
        // Read the actual behavior from contract's public owner and balances
        uint256 ownerBalAfter = owner.balance;
        // The property: owner balance should be at least ownerBalBefore (monotonic) and should have increased by sendAmount when call succeeded.
        // We assert that ownerBalAfter >= ownerBalBefore + 0 (monotonic increase). To make this a strict distinguishing property we assert owner received the funds.
        // Single assertion reading c's public surface: check owner balance increased by sendAmount and contract has zero balance.
        // We must make exactly one assertTrue reading c's actual behavior; compose it from address(c).balance==0 and owner balance increased by sendAmount.

        bool ok = (address(c).balance == 0 && ownerBalAfter >= ownerBalBefore + sendAmount);
        assertTrue(ok);
    }
}

